            this.el.innerHTML = '';
            const W = Math.max(160, this.el.clientWidth || this.el.parentElement?.clientWidth || 320);
            const H = o.height;
            const svg = el('svg', { width: '100%', height: H, viewBox: `0 0 ${W} ${H}`, class: 'awg-chart-svg' }, this.el);
            this._svg = svg; this._W = W; this._H = H;

